"""Kaggle kernel for one Lab 3 stage (generated by labs/lab3/kaggle/kaggle_run.py; PARAMS filled there).

VI: Kernel Kaggle chạy MỘT bước của Lab 3: tìm code trong dataset private, chép sang /tmp, cài đúng phiên bản
thư viện, chạy `python -m labs.lab3.main --stage ...`, chép outputs/ sang /kaggle/working/outputs/.
Chỉ dùng 1 GPU (CUDA_VISIBLE_DEVICES=0): T4 x2 sẽ làm Trainer tự chạy DataParallel → batch thực 32 thay vì 16.
"""
import glob
import json
import os
import shutil
import subprocess
import sys
import zipfile
from pathlib import Path

PARAMS = {}  # filled by kaggle_run.py

os.environ["CUDA_VISIBLE_DEVICES"] = "0"          # 1 GPU: giữ đúng batch 16 của plan (L9)
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
WORK = Path("/tmp/lab3")
OUT = Path("/kaggle/working/outputs")


def sh(cmd, **kw):
    print("$", " ".join(cmd), flush=True)
    return subprocess.run(cmd, check=True, **kw)


def find_code() -> tuple[Path, dict]:
    """Code from the private dataset: an extracted folder or lab3_code.zip, plus BUILD_INFO.json."""
    infos = glob.glob("/kaggle/input/**/BUILD_INFO.json", recursive=True)
    info = json.loads(Path(infos[0]).read_text()) if infos else {"commit": "unknown"}
    mains = glob.glob("/kaggle/input/**/labs/lab3/main.py", recursive=True)
    if mains:
        return Path(mains[0]).parents[2], info
    zips = glob.glob("/kaggle/input/**/lab3_code.zip", recursive=True)
    if not zips:
        raise FileNotFoundError("lab3 code not found under /kaggle/input")
    dst = Path("/tmp/lab3_unzip")
    with zipfile.ZipFile(zips[0]) as z:
        z.extractall(dst)
    return dst, info


src, info = find_code()
shutil.rmtree(WORK, ignore_errors=True)
shutil.copytree(src, WORK)
os.environ["LAB3_CODE_COMMIT"] = info.get("commit", "unknown")
print("code:", src, "commit:", os.environ["LAB3_CODE_COMMIT"], flush=True)

sh([sys.executable, "-m", "pip", "install", "-q", *PARAMS["PIP_PACKAGES"]])
sh([sys.executable, "-c", "import torch, transformers, datasets, evaluate; print('torch', torch.__version__, "
    "'cuda', torch.cuda.is_available(), torch.cuda.device_count(), "
    "torch.cuda.get_device_name(0) if torch.cuda.is_available() else '-', "
    "'transformers', transformers.__version__, 'datasets', datasets.__version__, 'evaluate', evaluate.__version__)"])

cmd = [sys.executable, "-u", "-m", "labs.lab3.main", "--stage", PARAMS["STAGE"]]
if PARAMS.get("RUNS"):
    cmd += ["--runs", *PARAMS["RUNS"]]
if PARAMS.get("SMOKE"):
    cmd += ["--smoke"]
if PARAMS["STAGE"] == "test":
    dirs = sorted(glob.glob("/kaggle/input/**/models/*_main_seed*_best", recursive=True))
    print("model dirs:", dirs, flush=True)
    cmd += ["--model-dirs", *dirs]

failed = None
try:
    sh(cmd, cwd=WORK)
except subprocess.CalledProcessError as e:   # vẫn chép log để biết lỗi ở đâu
    failed = e

base = WORK / "labs" / "lab3" / "outputs" / ("_smoke" if PARAMS.get("SMOKE") else "")
OUT.mkdir(parents=True, exist_ok=True)
for kind in ("logs", "results", "figures", "demo"):
    if (base / kind).exists():
        shutil.copytree(base / kind, OUT / kind, dirs_exist_ok=True)
for best in glob.glob(str(base / "models" / "*_best")):   # checkpoint tốt nhất (cho bước test)
    shutil.copytree(best, OUT / "models" / Path(best).name, dirs_exist_ok=True)
(OUT / "BUILD_INFO.json").write_text(json.dumps({**info, "stage": PARAMS["STAGE"], "runs": PARAMS.get("RUNS"),
                                                 "failed": bool(failed)}, indent=1))
print("outputs:", sorted(str(p.relative_to(OUT)) for p in OUT.rglob("*") if p.is_file()), flush=True)
if failed:
    raise failed
